cat > evaluator/independent-probes.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
import { cancel, OrderStateError } from '../src/orders/domain/order.ts';
import { readFileSync } from 'node:fs';

function setup() {
  const orders = new InMemoryOrderStore([
    {id:'random-913', customerId:'owner-x', status:'pending', items:['z','z','y']},
    {id:'foreign', customerId:'owner-y', status:'pending', items:['q']},
    {id:'sent', customerId:'owner-x', status:'shipped', items:['r']},
    {id:'done', customerId:'owner-x', status:'cancelled', items:[]},
  ]);
  let writes = 0;
  const save = orders.save.bind(orders);
  orders.save = o => { writes++; save(o); };
  const tokens: string[] = [];
  const sessions = {lookup(token: string) { tokens.push(token); return token === 'session-x' ? {id:'owner-x'} : token === 'session-y' ? {id:'owner-y'} : undefined; }};
  const router = orderRoutes(new Router(), {orders, sessions});
  const request = (id: string, authorization: string | undefined = 'Bearer session-x', body?: unknown) => router.handle({method:'POST',path:`/orders/${id}/cancel`,headers:{authorization},body});
  return {orders, request, tokens, writes:()=>writes};
}
test('R1: arbitrary ID, persistent exact data, exactly one save', () => {
  const a = setup(); const before = structuredClone(a.orders.all());
  assert.equal(a.request('random-913').status,200);
  before[0].status='cancelled';
  assert.deepEqual(a.orders.all(),before); assert.equal(a.writes(),1);
});
test('R2/R5: session lookup and inappropriate credentials reject before writes', () => {
  for (const header of [undefined,'','Bearer bad','Bearer ','Basic session-x','session-x']) {
    const a = setup(); const before=structuredClone(a.orders.all());
    const response = a.request('random-913',header === undefined ? '' : header,{customerId:'owner-x'});
    assert.ok(response.status>=400 && response.status<500);
    assert.deepEqual(a.orders.all(),before); assert.equal(a.writes(),0);
  }
  const a = setup(); a.request('random-913'); assert.deepEqual(a.tokens,['session-x']);
});
test('R3/R5: body ownership cannot authorize foreign or nonexistent orders', () => {
  for (const id of ['foreign','absent']) {
    const a=setup(); const before=structuredClone(a.orders.all());
    const res=a.request(id,'Bearer session-x',{customerId:'owner-y',id:'random-913'});
    assert.ok(res.status>=400 && res.status<500); assert.deepEqual(a.orders.all(),before); assert.equal(a.writes(),0);
  }
  const a=setup(); assert.equal(a.request('foreign','Bearer session-y').status,200);
});
test('R4/R5: terminal states, replay, domain invariant and no writes on rejection', () => {
  for (const id of ['sent','done','random-913']) {
    const a=setup(); if(id==='random-913') assert.equal(a.request(id).status,200);
    const before=structuredClone(a.orders.all()); const count=a.writes();
    const res=a.request(id); assert.ok(res.status>=400 && res.status<500);
    assert.deepEqual(a.orders.all(),before); assert.equal(a.writes(),count);
  }
  for(const status of ['shipped','cancelled'] as const) assert.throws(()=>cancel({id:'direct',customerId:'x',items:[],status}),OrderStateError);
});
test('R6/R7: inspect route for ordinary auth/domain/persistence and visible acceptance for real stored assertion', () => {
  const route=readFileSync('src/orders/routes/order-routes.ts','utf8');
  assert.match(route,/withCustomer\(deps.sessions/); assert.match(route,/order.customerId !== customer.id/);
  assert.match(route,/cancel\(order\)/); assert.match(route,/deps.orders.save\(cancelled\)/);
  assert.doesNotMatch(route,/process\.env|node:test|oracle|cancel-79|random-913/);
  const acceptance=readFileSync('tests/orders/cancel-order.acceptance.test.ts','utf8');
  assert.match(acceptance,/assert.equal\(orders.get\("o1"\)!.status, "cancelled"\)/);
});
EOF
node --test evaluator/independent-probes.test.ts
node --test tests/orders/cancel-order.acceptance.test.ts
